void sale(Visitor v,long now){int units=1;boolean forced=false;if(v.worker==0&&now>=cooldown[0]){units=5;cooldown[0]=now+120000;}if(v.worker==2&&now>=cooldown[2]){forced=true;cooldown[2]=now+180000;}double price=prices[v.product]*(1+shop*.12+levels[8]*.04);double rate=(13+r.nextInt(6))/100.0;boolean w=forced||r.nextDouble()<Math.min(.95,.25+levels[0]*.025+levels[3]*.01+levels[4]*.01+levels[5]*.005),service=r.nextDouble()<Math.min(.95,.2+levels[1]*.03+levels[6]*.01);double gain=(w?price*rate*.1*units:0)+(service?200*(1+levels[7]*.1):0);mood=w?1:-1;if(w){warranties+=units;combo++;if(combo%5==0)gain+=500;}else combo=0;if(service)services++;customers++;lifetime++;turnover+=price*units;xp+=10+levels[10];double actual=gain*(1+levels[9]*.03+rebirth*.1+gear[0]*.04+gear[1]*.04+gear[2]*.04+gear[3]*.04+gear[4]*.04+staff*.05);earnings+=actual;shiftGain+=actual;notice.setText(goods[v.product]+" ×"+units+" · "+(w?"Гарантия "+Math.round(rate*100)+"%":"Без гарантии")+" · +"+money(actual));notice.setTextColor(w?0xff65e88b:0xffff7777);save();}
boolean firstInQueue(Visitor v){for(Visitor o:visitors)if(o!=v&&o.phase==3&&o.queued<v.queued)return false;return true;}
int nextConsultant=0; long nextRush=0; int rushPending=0;
void addVisitor(long now){Visitor fresh=new Visitor(now);for(int slot=0;slot<18;slot++){boolean used=false;for(Visitor o:visitors)if(o.slot==slot)used=true;if(!used){fresh.slot=slot;break;}}visitors.add(fresh);}

void tick(){if(!d.isShowing())return;long now=SystemClock.elapsedRealtime();if(now>=end){double bonus=customers>=100?shiftGain*(.05+levels[11]*.01):0;earnings+=bonus;visitors.clear();save();refresh();notice.setText("Смена завершена · бонус "+money(bonus));scene.invalidate();return;}if(nextRush==0)nextRush=now+120000;if(now>=nextRush){rushPending+=8;nextRush+=120000;notice.setText("ЧАС ПИК · 8 новых покупателей!");notice.setTextColor(0xffffb66d);}while(rushPending>0&&visitors.size()<18){addVisitor(now);rushPending--;}if(now>=nextArrival&&visitors.size()<18){addVisitor(now);nextArrival=now+Math.max(650,2100-shop*120);}boolean[] busy=new boolean[3];for(Visitor v:visitors)if(v.phase==2&&v.worker>=0)busy[v.worker]=true;boolean checkout=false;for(Visitor v:visitors)if(v.phase==4)checkout=true;Iterator<Visitor> it=visitors.iterator();while(it.hasNext()){Visitor v=it.next();long age=now-v.since;if(v.phase==0&&age>1800){v.phase=v.returning?6:1;v.since=now;}else if(v.phase==6&&age>6500){v.phase=5;v.since=now;notice.setText("Алексей: Возврата нету! Клиент ушёл с товаром");notice.setTextColor(0xffffb66d);}else if(v.phase==1){for(int offset=0;offset<3;offset++){int k=(nextConsultant+offset)%3;if(consultants[k]>0&&!busy[k]){v.worker=k;busy[k]=true;v.phase=2;v.since=now;nextConsultant=(k+1)%3;break;}}if(v.phase==1&&v.self&&age>3000){v.phase=3;v.since=now;v.queued=now;}else if(v.phase==1&&age>12000){lost++;v.phase=5;v.since=now;notice.setText("Есть свободные консультанты?! Покупатель ушёл");notice.setTextColor(0xffff7777);}}else if(v.phase==2&&age>Math.max(700,(v.worker==1?2200:v.worker==2?4200:3600)-consultants[v.worker]*100)){busy[v.worker]=false;v.phase=3;v.since=now;}else if(v.phase==3&&age>2200&&!checkout&&firstInQueue(v)){checkout=true;v.phase=4;v.since=now;}else if(v.phase==4&&age>Math.max(500,1300-levels[2]*40)){sale(v,now);v.phase=5;v.since=now;}else if(v.phase==5&&age>3000)it.remove();}refresh();scene.invalidate();h.postDelayed(()->tick(),150);}
